update sdsshop.u_m_stock
   set goodsname = #{goodsName},
       spec = #{spec},
       unit = #{unit},
       warename = #{wareName},
       physicalqty = #{physicalQty},
       lockedqty = #{lockedQty},
       totalcostamount = #{totalCostAmount},
       avgcostprice = #{avgCostPrice},
       lastupdated = sysdate()
 where shop_code = #{shopCode}
   and goodscode = #{goodsCode}
   and warecode = #{wareCode}
   and qualityflag = #{qualityFlag}
   and onhandflag = #{onhandFlag}

