mapper.update:
update sdsshop.u_m_stock
   set avgcostprice = case
           when (physicalqty + #{adjustQty}) > 0
           then greatest(totalcostamount + #{costAmount}, 0) / (physicalqty + #{adjustQty})
           else 0
       end,
       totalcostamount = case
           when (physicalqty + #{adjustQty}) = 0 then 0
           else greatest(totalcostamount + #{costAmount}, 0)
       end,
       physicalqty = physicalqty + #{adjustQty},
       version = version + 1,
       lastupdated = sysdate()
 where shop_code = #{shopCode}
   and goodscode = #{goodsCode}
   and warecode = #{wareCode}

   and (physicalqty + #{adjustQty}) >= 0
   and (physicalqty + #{adjustQty}) >= lockedqty

update sdsshop.u_m_stock
   set lockedqty = lockedqty + #{adjustLockedQty},
       version = version + 1,
       lastupdated = sysdate()
 where shop_code = #{shopCode}
   and goodscode = #{goodsCode}
   and warecode = #{wareCode}

   and (lockedqty + #{adjustLockedQty}) >= 0
   and (physicalqty - lockedqty - #{adjustLockedQty}) >= 0

